/// <summary>
/// COC for Picking list registration update form
/// </summary>
[ExtensionOf(formControlStr(WMSPickingRegistration, PickAllButton))]
final class METWMSPickingRegistration_UpdateButtonCtrl_Extension
{
}

Method.Source:
/// <summary>
/// set clicked method
/// </summary>
void  clicked()
{
    next clicked();

    FormControl             formButtonControl           = any2Object(this) as FormControl;
    FormDataSource          wMSOrderTrans_ds            = formButtonControl.formRun().dataSource(tableStr(WMSOrderTrans));
    WMSOrderTrans           wMSOrderTrans               = wMSOrderTrans_ds.cursor();
    RecId                   preViousRecId               = 0;

    while (wMSOrderTrans.RecId != 0 && preViousRecId != wMSOrderTrans.RecId)
    {
        preViousRecId = wMSOrderTrans.RecId;

        this.updatePickedQty(wMSOrderTrans.RecId, wMSOrderTrans.qty);

        wMSOrderTrans_ds.next();
        wMSOrderTrans = wMSOrderTrans_ds.cursor();
    }      
}

/// <summary>
/// Update picked qty
/// </summary>
/// <param name = "_wMSOrderTransRecId">WMSOrderTrans RecId</param>
/// <param name = "_qty">WMSOrderTrans qty</param>
public void updatePickedQty(RefRecId _wMSOrderTransRecId, Qty _qty)
{
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;

    ttsbegin;
    update_recordset metSalesOrderShipmentLoadLines
        setting PickedQty = _qty
            where metSalesOrderShipmentLoadLines.WMSOrderTransRecId == _wMSOrderTransRecId;
    ttscommit;
}
